/* eslint-disable */
export default {
  props: {
    EditBillingSubDialog: Boolean,
    ViewInfo: Object
  },
  data() {
    return {
      price: "",
      quantity: "",
      gstTax: "",
      unit: ""
    };
  },
  watch: {
    EditBillingSubDialog: {
      async handler() {
        if (this.EditBillingSubDialog == true) {
          this.price = this.ViewInfo.price;
          this.quantity = this.ViewInfo.quantity;
          this.gstTax = this.ViewInfo.tax;
          this.unit = this.ViewInfo.unit;
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    is_number(evt) {
      evt = evt ? evt : window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      } else {
        return true;
      }
    },
    process(event) {
      if (event.type == "paste") {
        var clipboardData = event.clipboardData || window.clipboardData;
        var pastedData = clipboardData.getData("Text");
        if (isNaN(pastedData)) {
          event.preventDefault();
        } else {
          return;
        }
      }
      var keyCode = event.keyCode || event.which;
      if (keyCode >= 96 && keyCode <= 105) {
        keyCode -= 48;
      }
      var charValue = String.fromCharCode(keyCode);
      if (isNaN(parseInt(charValue)) && event.keyCode != 8) {
        event.preventDefault();
      }
    },
    save_deatails() {
      if (this.$refs.form.validate()) {
        var EditedData = {
          price: this.price,
          quantity: this.quantity,
          gstTax: this.gstTax,
          editedValue: this.ViewInfo,
          unit: this.unit
        };
        // console.log("SubData", EditedData)
        this.$emit("successData", EditedData);
      }
    }
  }
};
